// Shared certificate signature assets, embedded as base64 PNG data URIs.
//
// Why base64 and not a plain <img src="/images/...">: the server-side PDF
// (certificatePdf.ts) runs inside a Cloudflare Worker at issuance time, with
// no filesystem and no same-origin fetch of /public assets available. jsPDF's
// addImage() needs the actual image bytes in hand either way, so both the
// server-side generator and the client-side "Download PDF" button import
// these same constants — one copy of the image data, guaranteed identical
// output in the emailed PDF and the one a learner downloads later.
//
// Sourced from signed originals: Muhammad Sohail's signature (black ink) and
// Sehar Waheed's signature (blue ink in the original, recoloured to match —
// see CLAUDE.md/CHANGES.md if regenerating). Both are trimmed to their ink
// bounding box on a transparent background so they drop straight onto the
// certificate paper with no visible edges.

export const SIGNATURE_SOHAIL = {
  dataUri: 'data:image/png;base64,',
  width: 480,
  height: 279,
};

export const SIGNATURE_SEHAR = {
  dataUri: 'data:image/png;base64,',
  width: 480,
  height: 190,
};

// Real IBM Plex Mono font files (OFL-licensed, from Google Fonts), embedded
// so the PDF's monospace text — eyebrow, date, footer, signature roles —
// is the exact same typeface as the website's --font-mono, not jsPDF's
// built-in Courier standing in for it. Regular + Bold covers every mono
// usage on the certificate.
export const FONT_MONO_REGULAR_BASE64 = '';
export const FONT_MONO_BOLD_BASE64 = '';
